<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {api,useLoad,useCommand,PageHeader,Feedback,EmptyState,StatusBadge,session,type DataRow} from '@tradeflow/ui'
import {useRows,text,row,permits} from '../data'
import Pagination from '../components/Pagination.vue'
import RecordDetail from '../components/RecordDetail.vue'
const base='/api/v1/admin/reconciliation',tab=ref('runs'),no=ref(''),resource=ref('runs'),visible=ref(false),modal=ref(''),reason=ref(''),start=ref(''),end=ref(''),cutoff=ref(''),businessNo=ref(''),type=ref('PAYMENT'),actionQuery=ref(''),localError=ref(''),notice=ref('')
const list=useRows(()=>base+'/'+tab.value,'array')
const detail=useLoad<DataRow>(signal=>api(base+'/'+resource.value+'/'+encodeURIComponent(no.value),{signal}))
const observations=useRows(()=>base+'/'+resource.value+'/'+encodeURIComponent(no.value)+'/observations','array')
const command=useCommand('admin-reconciliation')
let generation=0
onBeforeUnmount(()=>{generation++})
const columns=computed(()=>tab.value==='runs'?[['task_no','批次编号'],['state','当前状态'],['consecutive_failures','连续异常'],['created_at','创建时间'],['last_error','最近异常']]:[['task_no','差异编号'],['transaction_type','交易类型'],['business_no','业务编号'],['issue_type','差异类型'],['state','当前状态']])
function closeDetail(){generation++;visible.value=false;detail.clear();observations.clear()}
async function open(kind:string,value:unknown){const g=++generation;resource.value=kind;no.value=String(value);visible.value=true;detail.clear();observations.reset();await detail.reload();if(g===generation&&visible.value&&kind!=='actions')await observations.reload()}
/** 默认选择已结束的UTC自然日，cutoff为账期结束后5分钟且已过当前时间，避免把未到宽限窗口的账期提交给服务端。 */
function defaults(){const now=new Date(),today=Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate());let endMs=today;if(Date.now()<today+300000)endMs-=86400000;start.value=new Date(endMs-86400000).toISOString();end.value=new Date(endMs).toISOString();cutoff.value=new Date(endMs+300000).toISOString()}
function create(kind:string){generation++;modal.value=kind;reason.value='';localError.value='';if(kind==='create')defaults()}
function closeModal(){generation++;modal.value=''}
/** 平台命令带原因与稳定幂等键，仅重新查询/修复既有事实；202仅受理，后续GET查询真实执行状态。 */
async function submit(){localError.value='';if(!reason.value.trim()){localError.value='请填写平台操作原因';return}const kind=modal.value,g=generation;let path='',body:DataRow={reason:reason.value.trim()};try{
 if(kind==='create'){const s=Date.parse(start.value),e=Date.parse(end.value),c=Date.parse(cutoff.value);if(![s,e,c].every(Number.isFinite)||s>=e||e-s>31*86400000||c-e<300000||c>Date.now())throw Error('请输入合法UTC账期：开始早于结束、跨度不超过31天、cutoff至少晚5分钟且不晚于当前时间');body={...body,start:new Date(s).toISOString(),end:new Date(e).toISOString(),cutoff:new Date(c).toISOString()};path=base+'/runs'}
 else if(kind==='check'){if(!/^[A-Za-z0-9_-]{1,64}$/.test(businessNo.value))throw Error('请输入合法支付或退款业务编号');body={...body,type:type.value,businessNo:businessNo.value};path=base+'/checks'}
 else {const current=detail.data.value;if(!current||!permits(current,kind==='repair'?'REPAIR':'RETRY'))return;path=base+'/'+resource.value+'/'+encodeURIComponent(no.value)+'/'+(kind==='repair'?'repair':'retry')}
 const result=await command.run(kind+':'+path,body,key=>api<unknown>(path,{method:'POST',body,key}));if(g!==generation||result===undefined)return;await command.reset();if(g!==generation)return;modal.value='';notice.value=`请求已受理，记录 ${text(row(result).task_no)}，当前状态 ${text(row(result).state)}。请查询记录核对后续执行结果。`;const returned=text(row(result).task_no);await list.reload();if(g!==generation)return;if(returned!=='—')await open(kind==='create'?'runs':kind==='repair'||kind==='check'?'actions':resource.value,returned)
 }catch(e){if(g===generation)localError.value=e instanceof Error?e.message:'输入不合法'}
}
function queryAction(){if(!/^[A-Za-z0-9_-]{1,64}$/.test(actionQuery.value)){localError.value='请输入合法的动作编号';return}localError.value='';void open('actions',actionQuery.value)}
watch(tab,()=>{closeDetail();list.reset();void list.reload()})
watch(()=>session.user?.userId,()=>{closeDetail();closeModal();list.clear();notice.value=''})
onMounted(()=>list.reload())
</script>
<template><PageHeader title="交易对账" description="对账批次保留原始观察，差异修复沿用支付与退款的权威事实。"><template #actions><ElButton type="primary" @click="create('create')">创建对账批次</ElButton></template></PageHeader><p v-if="notice" class="notice" role="status">{{notice}}</p><section class="panel"><div class="toolbar"><div class="toolbar-controls"><label for="action-query">动作编号</label><ElInput id="action-query" v-model="actionQuery" placeholder="ra_…" style="width:260px" @keyup.enter="queryAction"/><ElButton @click="queryAction">查询动作</ElButton><ElButton @click="create('check')">定向核查交易</ElButton></div></div><Feedback :error="localError"/><ElTabs v-model="tab"><ElTabPane label="对账批次" name="runs"/><ElTabPane label="差异记录" name="issues"/></ElTabs><div class="toolbar"><span class="muted">{{tab==='runs'?'UTC账期 · 独立运行与历史观察':'按稳定业务编号聚合的差异 · 保留每轮观察'}}</span><ElButton :loading="list.loading.value" @click="list.reload">刷新列表</ElButton></div><Feedback :loading="list.loading.value" :error="list.error.value"/><template v-if="!list.loading.value&&!list.error.value"><EmptyState v-if="!list.items.value.length" :title="tab==='runs'?'当前页暂无对账批次':'当前页暂无差异记录'"/><ElTable v-else :data="list.items.value"><ElTableColumn v-for="col in columns" :key="col[0]" :label="col[1]" :min-width="col[0]?.includes('no')?260:140"><template #default="{row}"><StatusBadge v-if="col[0]==='state'" :status="text(row.state)"/><span v-else>{{text(row[col[0]||''])}}</span></template></ElTableColumn><ElTableColumn label="操作" width="140"><template #default="{row}"><ElButton @click="open(tab,row.task_no)">查看详情</ElButton></template></ElTableColumn></ElTable></template><Pagination :page="list.page.value" :count="list.items.value.length" :has-next="list.hasNext.value" :loading="list.loading.value" @change="list.change"/></section>
<ElDialog :model-value="visible" :title="resource==='runs'?'对账批次详情':resource==='issues'?'对账差异详情':'修复 / 核查动作详情'" width="900px" @close="closeDetail"><Feedback :loading="detail.loading.value" :error="detail.error.value"/><template v-if="detail.data.value"><RecordDetail :value="detail.data.value"/><div class="inline-actions"><ElButton v-if="permits(detail.data.value,'RETRY')" type="primary" @click="create('retry')">重试原记录</ElButton><ElButton v-if="resource==='issues'&&permits(detail.data.value,'REPAIR')" type="primary" @click="create('repair')">发起差异修复</ElButton><ElButton v-if="resource==='issues'&&detail.data.value.action_no" @click="open('actions',detail.data.value.action_no)">查看关联动作</ElButton><ElButton @click="detail.reload">刷新状态</ElButton></div><template v-if="resource!=='actions'"><h3 class="section-title">独立历史观察</h3><Feedback :loading="observations.loading.value" :error="observations.error.value"/><template v-if="!observations.loading.value&&!observations.error.value"><EmptyState v-if="!observations.items.value.length" title="当前页暂无历史观察"/><div v-for="(observation,index) in observations.items.value" :key="index" class="panel"><RecordDetail :value="observation"/></div></template><Pagination :page="observations.page.value" :count="observations.items.value.length" :has-next="observations.hasNext.value" :loading="observations.loading.value" @change="observations.change"/></template></template></ElDialog>
<ElDialog :model-value="!!modal" :title="modal==='create'?'创建对账批次':modal==='check'?'定向核查交易':modal==='repair'?'发起差异修复':'重试原记录'" width="640px" @close="closeModal"><ElForm label-position="top" @submit.prevent="submit"><template v-if="modal==='create'"><p class="notice">所有时间显式使用UTC（ISO 8601的Z结尾）；cutoff至少晚于账期结束5分钟，且不能晚于当前时间。</p><ElFormItem label="账期开始（UTC）" required><ElInput v-model="start" placeholder="2026-10-22T00:00:00.000Z"/></ElFormItem><ElFormItem label="账期结束（UTC）" required><ElInput v-model="end"/></ElFormItem><ElFormItem label="快照截止cutoff（UTC）" required><ElInput v-model="cutoff"/></ElFormItem></template><template v-else-if="modal==='check'"><ElFormItem label="交易类型" required><ElSelect v-model="type"><ElOption label="支付" value="PAYMENT"/><ElOption label="退款" value="REFUND"/></ElSelect></ElFormItem><ElFormItem label="支付或退款业务编号" required><ElInput v-model="businessNo"/></ElFormItem></template><p v-else class="notice">原编号：{{no}}。请求受理后，实际修复进度由后台继续查询和确认。</p><ElFormItem label="操作原因" required><ElInput v-model="reason" type="textarea" maxlength="500" :rows="3"/></ElFormItem><Feedback :error="localError||command.error.value"/><ElButton native-type="submit" type="primary" :loading="command.busy.value">提交请求</ElButton><ElButton @click="closeModal">关闭</ElButton></ElForm></ElDialog></template>
